export function spawnGuest(id: string): Player {
  return {
    id,
    x: NAVE_SPAWN_X,
    y: NAVE_SPAWN_Y,
    guest: true,
    aura: 0,
    bestand: 0,
    winke: 0,
    hp: MAX_HP,
    strikeCd: 0,
    readiness: 0,
    beats: emptyBeats(),
    weather: emptyWeather(),
    namedWeather: false,
    locked: false,
    heard: "",
    serial: null,
    wink: "",
    inCare: false,
    inM3: false,
    current: "",
    cultWink: false,
    fakeWinke: 0,
    house: "",
    messenger: "",
    winkSchool: "",
    flagged: false,
    banked: 0,
    lastKillId: "",
    spectated: 0,
    claims: [],
    exhibitT: 0,
    insured: false,
    lastCareX: 0,
    lastCareY: 0,
    damaged: 0,
    cultMark: false,
    stipend: 0,
    storm: false,
    ruinBack: false,
    restraint: false,
    surface: false,
    filmRoom: "",
    historyLog: emptyLog(),
    partyOf: "",
    truceUntil: 0,
  };
}

function bumpLog(
  p: Player,
  patch: { passings?: number; buried?: number; looted?: number; house?: House },
): Player {
  const houses = [...p.historyLog.houses];
  if (patch.house && !houses.includes(patch.house)) houses.push(patch.house);
  return {
    ...p,
    historyLog: {
      passings: p.historyLog.passings + (patch.passings ?? 0),
      buried: p.historyLog.buried + (patch.buried ?? 0),
      looted: p.historyLog.looted + (patch.looted ?? 0),
      houses,
    },
  };
}

function continueAfterDeath(p: Player, patch: Partial<Player> = {}): Player {
  const paper = p.insured && !p.guest && !p.locked;
  const x = paper ? p.lastCareX || SHRINE.x : NAVE_SPAWN_X;
  const y = paper ? p.lastCareY || SHRINE.y : NAVE_SPAWN_Y;
  return {
    ...spawnGuest(p.id),
    bestand: p.bestand,
    winke: p.winke,
    aura: Math.max(0, p.aura - 8),
    guest: p.guest,
    beats: { ...p.beats },
    weather: { ...p.weather },
    namedWeather: p.namedWeather,
    locked: p.locked,
    heard: paper ? INSURANCE_USED : p.heard,
    serial: p.serial,
    wink: p.wink,
    inCare: p.inCare,
    inM3: p.inM3,
    current: p.current,
    cultWink: p.cultWink,
    cultMark: p.cultMark,
    house: p.house,
    messenger: p.messenger,
    flagged: p.flagged,
    banked: p.banked,
    lastKillId: p.lastKillId,
    claims: p.claims,
    exhibitT: p.exhibitT,
    spectated: p.spectated,
    lastCareX: p.lastCareX,
    lastCareY: p.lastCareY,
    insured: false,
    damaged: p.damaged + p.fakeWinke,
    fakeWinke: 0,
    stipend: p.stipend,
    storm: p.storm,
    ruinBack: p.ruinBack,
    restraint: p.restraint,
    surface: p.surface,
    filmRoom: p.filmRoom,
    winkSchool: p.winkSchool,
    historyLog: { ...p.historyLog, houses: [...p.historyLog.houses] },
    partyOf: p.partyOf,
    x,
    y,
    ...patch,
    ...(paper ? { heard: INSURANCE_USED, insured: false, x, y } : {}),
  };
}

export function guestCanClaim(_p: Player): boolean {
  return false;
}

export function damageFor(_p: Player): number {
  return STRIKE_DAMAGE;
}

export function stepPlayer(p: Player, intent: Intent, dt: number): Player {
  let vx = (intent.right ? 1 : 0) - (intent.left ? 1 : 0);
  let vy = (intent.down ? 1 : 0) - (intent.up ? 1 : 0);
  const len = Math.hypot(vx, vy) || 1;
  vx = (vx / len) * SPEED * dt;
  vy = (vy / len) * SPEED * dt;
  let x = p.x + vx;
  let y = p.y + vy;
  if (circleHitsWalls(x, y, BODY_R)) {
    if (!circleHitsWalls(p.x + vx, p.y, BODY_R)) {
      x = p.x + vx;
      y = p.y;
    } else if (!circleHitsWalls(p.x, p.y + vy, BODY_R)) {
      x = p.x;
      y = p.y + vy;
    } else {
      x = p.x;
      y = p.y;
    }
  }
  return { ...p, x, y, strikeCd: Math.max(0, p.strikeCd - dt) };
}

