export function tickWorld(w: WorldState, dt: number): WorldState {
  const now = w.now + dt;
  const players = new Map<string, Player>();
  for (const [id, p] of w.players) {
    const intent = w.intents.get(id) ?? { up: false, down: false, left: false, right: false };
    players.set(id, stepPlayer(p, intent, dt));
  }
  const afterClerks = tickClerks({ ...w, now, players }, dt);
  const afterWar = tickHouseWar(afterClerks, dt);
  const afterDecay = tickExhibit(afterWar, dt);
  const afterAura = tickAura(afterDecay, dt);
  const afterFlag = tickWetFlag(afterAura);
  return {
    ...afterFlag,
    wreckage: afterFlag.wreckage.filter((r) => r.until > now),
  };
}

function tickWetFlag(w: WorldState): WorldState {
  if (!wetGridDefaultFlag(w)) return w;
  const players = new Map(w.players);
  let changed = false;
  for (const [id, p] of players) {
    if (p.guest || p.locked || p.flagged || p.hp <= 0 || p.truceUntil > w.now) continue;
    if (!inWetGrid(p.x, p.y)) continue;
    players.set(id, { ...p, flagged: true });
    changed = true;
  }
  return changed ? { ...w, players } : w;
}

export function tickAura(w: WorldState, dt: number): WorldState {
  const players = new Map(w.players);
  let changed = false;
  for (const [id, p] of players) {
    const seed = p.guest ? 0 : auraSeed(p.serial ?? 0);
    const aura = auraTowardSeed({ aura: p.aura, seed, dt, slow: w.appearSlow, guest: p.guest });
    if (aura === p.aura) continue;
    players.set(id, { ...p, aura });
    changed = true;
  }
  return changed ? { ...w, players } : w;
}

export function tickExhibit(w: WorldState, dt: number): WorldState {
  const players = new Map(w.players);
  let changed = false;
  for (const [id, p] of players) {
    if (p.fakeWinke <= 0) continue;
    let exhibitT = p.exhibitT + dt;
    let fakeWinke = p.fakeWinke;
    let heard = p.heard;
    while (fakeWinke > 0 && exhibitT >= EXHIBIT_DECAY) {
      exhibitT -= EXHIBIT_DECAY;
      fakeWinke -= 1;
      heard = DECAY_COPY;
      changed = true;
    }
    if (exhibitT !== p.exhibitT || fakeWinke !== p.fakeWinke) {
      players.set(id, { ...p, exhibitT, fakeWinke, heard });
      changed = true;
    }
  }
  return changed ? { ...w, players } : w;
}

export function tickHouseWar(w: WorldState, dt: number): WorldState {
  if (!w.clearingOpen || w.war.winner) return w;
  const keep = { ...w.war.keep };
  for (const p of w.players.values()) {
    if (p.guest || p.locked || !p.house || p.hp <= 0) continue;
    if (!nearPoint(p.x, p.y, CLEARING_RING.x, CLEARING_RING.y, 64)) continue;
    keep[p.house] += dt;
  }
  return { ...w, war: resolveWar({ ...w.war, keep }, "keep") };
}

export function tickClerks(w: WorldState, dt: number): WorldState {
  const players = new Map(w.players);
  const clerks: Clerk[] = [];
  let wreckage = w.wreckage;
  for (const c of w.clerks) {
    if (c.hp <= 0) continue;
    const living = [...players.values()].filter((p) => p.hp > 0);
    const target = living.find((p) => nearPoint(p.x, p.y, c.x, c.y, CLERK_AGGRO));
    if (c.telegraph > 0) {
      const next = c.telegraph - dt;
      if (next <= 0 && target) {
        const hit = players.get(target.id)!;
        if (hit.restraint && intentMoving(w.intents.get(hit.id))) {
          players.set(hit.id, { ...hit, heard: DODGE_COPY });
          clerks.push({ ...c, telegraph: 0 });
          continue;
        }
        const hp = hit.hp - CLERK_DAMAGE;
        if (hp <= 0) {
          wreckage = [
            ...wreckage,
            { id: `w-${hit.id}-${w.now}`, x: hit.x, y: hit.y, fromId: hit.id, fromName: "Guest", until: w.now + 45 },
          ];
          players.set(hit.id, continueAfterDeath(hit, { heard: `${c.name} did their job.` }));
        } else {
          players.set(hit.id, { ...hit, hp });
        }
        clerks.push({ ...c, telegraph: 0 });
      } else {
        clerks.push({ ...c, telegraph: target ? Math.max(0, next) : 0 });
      }
    } else if (target) {
      clerks.push({ ...c, telegraph: CLERK_TELEGRAPH });
    } else {
      clerks.push({ ...c, telegraph: 0 });
    }
  }
  return { ...w, players, clerks, wreckage };
}

export function applyStrike(w: WorldState, attackerId: string): WorldState {
  const a = w.players.get(attackerId);
  if (!a || a.hp <= 0 || a.strikeCd > 0) return w;
  const players = new Map(w.players);
  const attacker = { ...a, strikeCd: STRIKE_COOLDOWN };
  players.set(attackerId, attacker);
  const dmg = damageFor(a);
  let wreckage = w.wreckage;
  let gestell = w.gestell;
  const duelGraves: { x: number; y: number }[] = [];
  const fallen = new Set<string>();
  let stormMark: { x: number; y: number } | null = null;
  let hitMark: { x: number; y: number } | null = null;
  const priorHeard = a.heard;
  for (const [id, b] of w.players) {
    if (id === attackerId || b.hp <= 0) continue;
    const dx = b.x - a.x;
    const dy = b.y - a.y;
    if (dx * dx + dy * dy > STRIKE_RANGE * STRIKE_RANGE) continue;
    if (!a.guest && (b.guest || b.locked)) {
      const k = players.get(attackerId)!;
      if (k.heard === priorHeard || k.heard === GUEST_GRIEF) {
        players.set(attackerId, { ...k, heard: GUEST_GRIEF });
      }
      continue;
    }
    if (b.restraint && intentMoving(w.intents.get(id))) {
      players.set(id, { ...b, heard: DODGE_COPY });
      const k = players.get(attackerId)!;
      players.set(attackerId, { ...k, heard: DODGE_WHIFF });
      continue;
    }
    const isFallen = alreadyFallen(b, w.wreckage);
    const geared = a.storm && !a.guest && stormProgress(b) && !isFallen;
    let hp = b.hp - dmg;
    hitMark = { x: b.x, y: b.y };
    if (hp <= 0) {
      wreckage = [
        ...wreckage,
        { id: `w-${id}-${w.now}`, x: b.x, y: b.y, fromId: id, fromName: b.guest ? "Guest" : "Angel", until: w.now + 45 },
      ];
      const grief = a.guest || b.guest || b.locked;
      const grave = w.wreckage.find(
        (r) => nearPoint(a.x, a.y, r.x, r.y, 72) && nearPoint(b.x, b.y, r.x, r.y, 72),
      );
      const ruinDuel = !grief && !!grave;
      const flaggedFight = !grief && a.flagged && b.flagged;
      const stormSkim = !grief && geared ? Math.floor(b.bestand * STORM_SKIM) : 0;
      const drop = (flaggedFight || ruinDuel ? Math.floor(b.bestand * 0.3) : 0) + stormSkim;
      const fakeDrop = (flaggedFight || ruinDuel) && b.fakeWinke > 0 ? 1 : 0;
      const camp = (flaggedFight || ruinDuel) && a.lastKillId === id;
      const killer = players.get(attackerId)!;
      players.set(attackerId, bumpLog({
        ...killer,
        bestand: killer.bestand + drop,
        fakeWinke: killer.fakeWinke + fakeDrop,
        aura: camp ? Math.max(0, killer.aura - 4) : killer.aura,
        lastKillId: id,
        beats: stormSkim ? { ...killer.beats, stormPress: true } : killer.beats,
        heard: grief
          ? GUEST_GRIEF
          : camp
            ? CAMP_COPY
            : stormSkim
              ? STORM_SKIM_COPY
              : ruinDuel
                ? DUEL_COPY
                : drop
                  ? SPOILS_COPY
                  : killer.heard,
        wink: stormSkim
          ? visibleWink(false, WINK_STORM_PRESS)
          : ruinDuel
            ? visibleWink(false, WINK_DUEL)
            : killer.wink,
      }, drop > 0 ? { looted: 1 } : {}));
      if (stormSkim) {
        stormMark = { x: b.x, y: b.y };
      }
      fallen.add(id);
      if (ruinDuel && grave) duelGraves.push(grave);
      players.set(
        id,
        continueAfterDeath({
          ...b,
          bestand: b.bestand - drop,
          fakeWinke: b.fakeWinke - fakeDrop,
        }),
      );
      if (camp) gestell = Math.min(100, gestell + 4);
    } else if (geared) {
      const crack = b.fakeWinke > 0 ? 1 : 0;
      players.set(id, {
        ...b,
        hp,
        damaged: b.damaged + crack,
        fakeWinke: Math.max(0, b.fakeWinke - crack),
        heard: STORM_PRESS,
      });
      const k = players.get(attackerId)!;
      players.set(attackerId, {
        ...k,
        beats: { ...k.beats, stormPress: true },
        heard: STORM_PRESS,
        wink: visibleWink(false, WINK_STORM_PRESS),
      });
      stormMark = { x: b.x, y: b.y };
    } else if (a.storm && !a.guest && isFallen) {
      players.set(id, { ...b, hp, heard: STORM_FALLEN });
      const k = players.get(attackerId)!;
      players.set(attackerId, { ...k, heard: STORM_FALLEN });
    } else {
      players.set(id, { ...b, hp });
    }
  }
  for (const grave of duelGraves) {
    for (const [sid, s] of players) {
      if (sid === attackerId || fallen.has(sid) || s.guest || s.locked || s.hp <= 0) continue;
      if (!nearPoint(s.x, s.y, grave.x, grave.y, 80)) continue;
      if (s.spectated >= SPECTATE_CAP) continue;
      players.set(sid, {
        ...s,
        spectated: s.spectated + 1,
        aura: s.aura + 1,
        heard: SPECTATE_COPY,
        wink: visibleWink(false, WINK_DUEL),
      });
    }
  }
  const clerks: Clerk[] = [];
  for (const c of w.clerks) {
    const dx = c.x - a.x;
    const dy = c.y - a.y;
    if (c.hp <= 0 || dx * dx + dy * dy > STRIKE_RANGE * STRIKE_RANGE) {
      if (c.hp > 0) clerks.push(c);
      continue;
    }
    const hp = c.hp - dmg;
    hitMark = { x: c.x, y: c.y };
    if (hp <= 0) {
      if (c.dummy) {
        clerks.push({ ...c, hp: CLERK_HP, telegraph: 0 });
        players.set(attackerId, { ...players.get(attackerId)!, heard: ARENA_HIT });
        continue;
      }
      wreckage = [
        ...wreckage,
        { id: `w-${c.id}-${w.now}`, x: c.x, y: c.y, fromId: c.id, fromName: c.name, until: w.now + 45 },
      ];
      players.set(attackerId, { ...players.get(attackerId)!, heard: `${c.name} falls. They were doing a job.` });
    } else {
      clerks.push({ ...c, hp });
    }
  }
  if (hitMark) {
    const k = players.get(attackerId)!;
    const first = !w.hitStopHeld;
    players.set(attackerId, {
      ...k,
      strikeCd: STRIKE_COOLDOWN + HIT_STOP,
      beats: { ...k.beats, hitStop: true },
      heard: first && k.heard === priorHeard ? HIT_STOP_COPY : k.heard,
      wink: first && k.heard === priorHeard ? visibleWink(k.guest, WINK_HIT_STOP) : k.wink,
    });
  }
  const stopPois = hitMark && !w.hitStopHeld
    ? (w.pois.some((poi) => poi.id === "hit-stop")
        ? w.pois.map((poi) => (poi.id === "hit-stop" ? hitStopPoi(hitMark.x, hitMark.y) : poi))
        : [...w.pois, hitStopPoi(hitMark.x, hitMark.y)])
    : w.pois;
  const stopSigns = hitMark && !w.hitStopHeld
    ? (w.signs.some((s) => s.id === "hit-stop")
        ? w.signs.map((s) => (s.id === "hit-stop" ? { ...HIT_STOP_PLAQUE, x: hitMark.x, y: hitMark.y } : s))
        : [...w.signs, { ...HIT_STOP_PLAQUE, x: hitMark.x, y: hitMark.y }])
    : w.signs;
  if (!stormMark) {
    return {
      ...w,
      players,
      wreckage,
      clerks,
      gestell,
      hitStopHeld: hitMark ? true : w.hitStopHeld,
      pois: stopPois,
      signs: stopSigns,
    };
  }
  const plaque = { ...STORM_PROGRESS_PLAQUE, x: stormMark.x, y: stormMark.y };
  const pois = stopPois.some((poi) => poi.id === "storm-progress")
    ? stopPois.map((poi) => (poi.id === "storm-progress" ? stormProgressPoi(stormMark.x, stormMark.y) : poi))
    : [...stopPois, stormProgressPoi(stormMark.x, stormMark.y)];
  const signs = stopSigns.some((s) => s.id === "storm-progress")
    ? stopSigns.map((s) => (s.id === "storm-progress" ? plaque : s))
    : [...stopSigns, plaque];
  return { ...w, players, wreckage, clerks, gestell, stormPressHeld: true, hitStopHeld: true, pois, signs };
}

export function applyAddressed(w: WorldState, playerId: string): WorldState {
  const p = w.players.get(playerId);
  if (!p || p.hp <= 0 || !nearPoint(p.x, p.y, 192, 400, 56)) return w;
  const players = new Map(w.players);
  if (p.guest || p.locked) {
    players.set(playerId, { ...p, heard: ADDRESSED_SPECTATOR, wink: visibleWink(true, WINK_ADDRESSED) });
    return { ...w, players };
  }
  if (!w.weatherNamed) {
    players.set(playerId, { ...p, heard: ADDRESSED_WEATHER });
    return { ...w, players };
  }
  if (p.aura < AURA_ADDRESS) {
    players.set(playerId, { ...p, heard: ADDRESSED_NEED });
    return { ...w, players };
  }
  if (w.addressedHeld && p.beats.addressed) {
    players.set(playerId, { ...p, heard: ADDRESSED_HELD, wink: visibleWink(false, WINK_ADDRESSED) });
    return { ...w, players };
  }
  players.set(playerId, {
    ...p,
    beats: { ...p.beats, addressed: true },
    heard: ADDRESSED_COPY,
    wink: visibleWink(false, WINK_ADDRESSED),
  });
  const pois = w.pois.some((poi) => poi.id === "addressed") ? w.pois : [...w.pois, addressedPoi()];
  const signs = w.signs.map((s) => (s.id === "safety-plaque" ? { ...ADDRESSED_PLAQUE } : s));
  return { ...w, players, addressedHeld: true, pois, signs };
}

export function applyParty(w: WorldState, playerId: string): WorldState {
  const p = w.players.get(playerId);
  if (!p || p.hp <= 0) return w;
  const other = [...w.players.values()].find(
    (o) => o.id !== playerId && o.hp > 0 && !o.guest && !o.locked && nearPoint(p.x, p.y, o.x, o.y, 56),
  );
  const players = new Map(w.players);
  if (p.guest || p.locked) {
    players.set(playerId, { ...p, heard: PARTY_SPECTATOR, wink: visibleWink(true, WINK_PARTY_WALK) });
    return { ...w, players };
  }
  if (!w.weatherNamed) {
    players.set(playerId, { ...p, heard: PARTY_NEED });
    return { ...w, players };
  }
  if (!other) {
    players.set(playerId, { ...p, heard: PARTY_NEED });
    return { ...w, players };
  }
  if (p.partyOf) return applyPart(w, playerId);
  if (w.partyHeld && p.beats.party && p.partyOf === other.id) {
    players.set(playerId, { ...p, heard: PARTY_HELD, wink: visibleWink(false, WINK_PARTY_WALK) });
    return { ...w, players };
  }
  players.set(playerId, {
    ...p,
    beats: { ...p.beats, party: true },
    partyOf: other.id,
    heard: PARTY_COPY,
    wink: visibleWink(false, WINK_PARTY_WALK),
  });
  players.set(other.id, {
    ...other,
    beats: { ...other.beats, party: true },
    partyOf: playerId,
    heard: PARTY_COPY,
    wink: visibleWink(false, WINK_PARTY_WALK),
  });
  const mx = Math.round((p.x + other.x) / 2);
  const my = Math.round((p.y + other.y) / 2);
  const plaque = { ...PARTY_WALK_PLAQUE, x: mx, y: my };
  const pois = w.pois.some((poi) => poi.id === "party-walk")
    ? w.pois.map((poi) => (poi.id === "party-walk" ? partyPoi(mx, my) : poi))
    : [...w.pois, partyPoi(mx, my)];
  const signs = w.signs.some((s) => s.id === "party-walk")
    ? w.signs.map((s) => (s.id === "party-walk" ? plaque : s))
    : [...w.signs, plaque];
  return { ...w, players, partyHeld: true, pois, signs };
}

export function applyPart(w: WorldState, playerId: string): WorldState {
  const p = w.players.get(playerId);
  if (!p || p.hp <= 0) return w;
  const players = new Map(w.players);
  if (p.guest || p.locked) {
    players.set(playerId, { ...p, heard: PART_SPECTATOR, wink: visibleWink(true, WINK_PART) });
    return { ...w, players };
  }
  if (!p.partyOf) {
    players.set(playerId, {
      ...p,
      heard: p.beats.parted ? PART_HELD : PART_NEED,
      wink: p.beats.parted ? visibleWink(false, WINK_PART) : p.wink,
    });
    return { ...w, players };
  }
  const mate = w.players.get(p.partyOf);
  players.set(playerId, {
    ...p,
    beats: { ...p.beats, parted: true },
    partyOf: "",
    heard: PART_COPY,
    wink: visibleWink(false, WINK_PART),
  });
  if (mate) {
    players.set(mate.id, {
      ...mate,
      beats: { ...mate.beats, parted: true },
      partyOf: mate.partyOf === playerId ? "" : mate.partyOf,
      heard: PART_COPY,
      wink: visibleWink(false, WINK_PART),
    });
  }
  const mx = mate ? Math.round((p.x + mate.x) / 2) : p.x;
  const my = mate ? Math.round((p.y + mate.y) / 2) : p.y;
  const plaque = { ...PART_PLAQUE, x: mx, y: my };
  const pois = w.pois.some((poi) => poi.id === "party-walk")
    ? w.pois.map((poi) => (poi.id === "party-walk" ? partPoi(mx, my) : poi))
    : [...w.pois, partPoi(mx, my)];
  const signs = w.signs.some((s) => s.id === "party-walk")
    ? w.signs.map((s) => (s.id === "party-walk" ? plaque : s))
    : [...w.signs, plaque];
  return { ...w, players, partyHeld: false, partedHeld: true, pois, signs };
}

export function applyHeavy(w: WorldState, playerId: string): WorldState {
  const before = applyStrike(w, playerId);
  if (before === w) return w;
  const p = before.players.get(playerId);
  if (!p) return before;
  const connected = p.beats.hitStop || before.hitStopHeld;
  const players = new Map(before.players);
  const first = !w.heavyHeld && connected;
  players.set(playerId, {
    ...p,
    strikeCd: connected ? STRIKE_COOLDOWN + HIT_STOP + HEAVY_HOLD : p.strikeCd,
    beats: { ...p.beats, heavy: true },
    heard: first ? HEAVY_COPY : p.heard,
    wink: first ? visibleWink(p.guest, WINK_HEAVY) : p.wink,
  });
  const clerks = before.clerks.map((c) => {
    if (c.hp <= 0 || c.telegraph <= 0) return c;
    if (!nearPoint(p.x, p.y, c.x, c.y, STRIKE_RANGE + 8)) return c;
    return { ...c, telegraph: 0 };
  });
  if (!first) return { ...before, players, clerks };
  const pois = before.pois.some((poi) => poi.id === "heavy")
    ? before.pois.map((poi) => (poi.id === "heavy" ? heavyPoi(p.x, p.y) : poi))
    : [...before.pois, heavyPoi(p.x, p.y)];
  const signs = before.signs.some((s) => s.id === "heavy")
    ? before.signs.map((s) => (s.id === "heavy" ? { ...HEAVY_PLAQUE, x: p.x, y: p.y } : s))
    : [...before.signs, { ...HEAVY_PLAQUE, x: p.x, y: p.y }];
  return { ...before, players, clerks, heavyHeld: true, pois, signs };
}

export function applyTruce(w: WorldState, playerId: string): WorldState {
  const p = w.players.get(playerId);
  if (!p || p.hp <= 0) return w;
  if (w.flagPeopleHeld && !w.trucePeopleHeld) return applyTrucePeople(w, playerId);
  const other = [...w.players.values()].find(
    (o) => o.id !== playerId && o.hp > 0 && !o.guest && !o.locked && o.flagged && nearPoint(p.x, p.y, o.x, o.y, 56),
  );
  const players = new Map(w.players);
  if (p.guest || p.locked) {
    players.set(playerId, { ...p, heard: TRUCE_SPECTATOR, wink: visibleWink(true, WINK_TRUCE) });
    return { ...w, players };
  }
  if (!p.flagged || !other) {
    players.set(playerId, {
      ...p,
      heard: p.beats.truce ? TRUCE_HELD : TRUCE_NEED,
      wink: p.beats.truce ? visibleWink(false, WINK_TRUCE) : p.wink,
    });
    return { ...w, players };
  }
  const until = w.now + TRUCE_HOLD;
  const first = !w.truceHeld;
  players.set(playerId, {
    ...p,
    flagged: false,
    truceUntil: until,
    beats: { ...p.beats, truce: true },
    heard: first ? TRUCE_COPY : TRUCE_HELD,
    wink: visibleWink(false, WINK_TRUCE),
  });
  players.set(other.id, {
    ...other,
    flagged: false,
    truceUntil: until,
    beats: { ...other.beats, truce: true },
    heard: first ? TRUCE_COPY : TRUCE_HELD,
    wink: visibleWink(false, WINK_TRUCE),
  });
  const mx = Math.round((p.x + other.x) / 2);
  const my = Math.round((p.y + other.y) / 2);
  const plaque = { ...TRUCE_PLAQUE, x: mx, y: my };
  const pois = w.pois.some((poi) => poi.id === "truce")
    ? w.pois.map((poi) => (poi.id === "truce" ? trucePoi(mx, my) : poi))
    : [...w.pois, trucePoi(mx, my)];
  const signs = w.signs.some((s) => s.id === "truce")
    ? w.signs.map((s) => (s.id === "truce" ? plaque : s))
    : [...w.signs, plaque];
  return { ...w, players, truceHeld: true, pois, signs };
}

export function applyHandoff(w: WorldState, playerId: string): WorldState {
  const p = w.players.get(playerId);
  if (!p || p.hp <= 0 || !nearPoint(p.x, p.y, CLEARING_STALL.x, CLEARING_STALL.y, 56)) return w;
  if (w.trucePeopleHeld && !w.handoffPeopleHeld) return applyHandoffPeople(w, playerId);
  const other = [...w.players.values()].find(
    (o) => o.id !== playerId && o.hp > 0 && !o.guest && !o.locked && nearPoint(p.x, p.y, o.x, o.y, 56),
  );
  const players = new Map(w.players);
  if (p.guest || p.locked) {
    players.set(playerId, { ...p, heard: HANDOFF_SPECTATOR, wink: visibleWink(true, WINK_HANDOFF) });
    return { ...w, players };
  }
  if (w.stallDark) {
    players.set(playerId, { ...p, heard: HANDOFF_DARK, wink: visibleWink(false, WINK_HANDOFF) });
    return { ...w, players };
  }
  if (p.cultWink) {
    players.set(playerId, { ...p, heard: HANDOFF_CULT, wink: visibleWink(false, WINK_HANDOFF) });
    return { ...w, players };
  }
  if (!other) {
    players.set(playerId, { ...p, heard: HANDOFF_NEED });
    return { ...w, players };
  }
  if (p.fakeWinke <= 0) {
    players.set(playerId, { ...p, heard: HANDOFF_NONE });
    return { ...w, players };
  }
  const spent = spendBestand(p, LISTING_FEE);
  if (!spent) {
    players.set(playerId, { ...p, heard: HANDOFF_FEE });
    return { ...w, players };
  }
  const first = !w.handoffHeld;
  players.set(playerId, {
    ...p,
    fakeWinke: p.fakeWinke - 1,
    bestand: spent.bestand,
    banked: spent.banked,
    aura: Math.max(0, p.aura - 1),
    beats: { ...p.beats, handoff: true },
    heard: vaultHeard(first ? HANDOFF_COPY : HANDOFF_AGAIN, spent.fromVault),
    wink: visibleWink(false, WINK_HANDOFF),
  });
  players.set(other.id, {
    ...other,
    fakeWinke: other.fakeWinke + 1,
    exhibitT: 0,
    heard: HANDOFF_COPY,
    wink: visibleWink(false, WINK_HANDOFF),
  });
  const pois = w.pois.some((poi) => poi.id === "stall-handoff")
    ? w.pois.map((poi) => (poi.id === "stall-handoff" ? handoffPoi() : poi))
    : [...w.pois, handoffPoi()];
  const signs = w.signs.some((s) => s.id === "stall-handoff")
    ? w.signs.map((s) => (s.id === "stall-handoff" ? { ...HANDOFF_PLAQUE } : s))
    : [...w.signs, { ...HANDOFF_PLAQUE }];
  return { ...w, players, handoffHeld: true, pois, signs };
}

export function applyNaraPerson(w: WorldState, playerId: string): WorldState {
  const p = w.players.get(playerId);
  if (!p || p.hp <= 0) return w;
  const players = new Map(w.players);
  if (p.guest || p.locked) {
    players.set(playerId, { ...p, heard: NARA_PERSON_SPECTATOR, wink: visibleWink(true, WINK_NARA_PERSON) });
    return { ...w, players };
  }
  if (!p.beats.funeral) {
    players.set(playerId, { ...p, heard: NARA_PERSON_NEED });
    return { ...w, players };
  }
  if (w.naraPersonHeld && p.beats.naraPerson) {
    players.set(playerId, { ...p, heard: NARA_PERSON_HELD, wink: visibleWink(false, WINK_NARA_PERSON) });
    return { ...w, players };
  }
  players.set(playerId, {
    ...p,
    beats: { ...p.beats, naraPerson: true, nara: true },
    heard: NARA_PERSON,
    wink: visibleWink(false, WINK_NARA_PERSON),
  });
  const pois = w.pois.some((poi) => poi.id === "nara-person") ? w.pois : [...w.pois, naraPersonPoi()];
  const signs = w.signs.some((s) => s.id === "nara-person") ? w.signs : [...w.signs, { ...NARA_PERSON_PLAQUE }];
  return { ...w, players, naraPersonHeld: true, pois, signs };
}

